// Helpers of the docs tests (docs_structure_test.cpp, docs_links_test.cpp): the Markdown files of the checkout, their
// lines outside code fences, heading anchors by GitHub's rules, and the `](target)` links.
#pragma once

#include <algorithm>
#include <cctype>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <map>
#include <set>
#include <sstream>
#include <string>
#include <vector>

#include "fa/core/fs.h"
#include "fa_test_paths.h"  // this checkout's paths (FA_REPO_ROOT), generated by CMake

namespace fa_docs_test {

namespace stdfs = std::filesystem;

constexpr std::uintmax_t kDocBudgetBytes = 61440;  // 60 KB

inline std::string read_all(const stdfs::path& p) {
    std::ifstream in(p, std::ios::binary);
    return std::string(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
}

// Path of `p` below the checkout, with '/' separators.
inline std::string rel_of(const stdfs::path& p) {
    return p.lexically_relative(stdfs::path(FA_REPO_ROOT)).generic_string();
}

inline bool starts_with(const std::string& s, const std::string& prefix) { return s.rfind(prefix, 0) == 0; }

inline std::vector<stdfs::path> markdown_files_under(const stdfs::path& dir) {
    std::vector<stdfs::path> out;
    for (const auto& e : stdfs::recursive_directory_iterator(dir))
        if (e.is_regular_file() && e.path().extension() == ".md") out.push_back(e.path());
    std::sort(out.begin(), out.end());
    return out;
}

// The generated references and the translations: outside the size budget and not embedded.
inline bool is_generated_or_translation(const std::string& rel) {
    return rel == "docs/COMPONENTS.md" || starts_with(rel, "docs/reference/") || starts_with(rel, "docs/i18n/");
}

// docs/ files the binary does not carry (tools/common/CMakeLists.txt, FA_EMBED_DOCS).
inline bool is_embedded_doc(const std::string& rel) {
    return starts_with(rel, "docs/") && !is_generated_or_translation(rel) && !starts_with(rel, "docs/design/");
}

struct Line {
    std::string text;
    bool inFence = false;  // inside a ``` or ~~~ block, or the fence line itself
};

inline std::vector<Line> split_lines(const std::string& text) {
    std::vector<Line> lines;
    std::istringstream in(text);
    std::string l;
    std::string fence;  // the opening fence marker while inside one
    while (std::getline(in, l)) {
        if (!l.empty() && l.back() == '\r') l.pop_back();
        size_t i = 0;
        while (i < l.size() && l[i] == ' ' && i < 3) ++i;
        const bool isFence = l.compare(i, 3, "```") == 0 || l.compare(i, 3, "~~~") == 0;
        Line line{l, !fence.empty() || isFence};
        if (isFence) {
            if (fence.empty())
                fence = l.substr(i, 3);
            else if (l.compare(i, 3, fence) == 0)
                fence.clear();
        }
        lines.push_back(std::move(line));
    }
    return lines;
}

// A code point GitHub's slugger drops: the punctuation, symbols, arrows, box drawing and emoji of Unicode (what is not
// a letter, a digit or a mark). Letters of every script stay.
inline bool is_unicode_punctuation(unsigned cp) {
    return (cp >= 0xA0 && cp <= 0xBF && cp != 0xAA && cp != 0xB5 && cp != 0xBA) || cp == 0xD7 || cp == 0xF7 ||
           (cp >= 0x2000 && cp <= 0x2BFF && !(cp >= 0x2070 && cp <= 0x209F && cp != 0x2072 && cp != 0x2073)) ||
           (cp >= 0x2E00 && cp <= 0x2E7F) || (cp >= 0x3000 && cp <= 0x303F) || (cp >= 0xFE10 && cp <= 0xFE6F) ||
           (cp >= 0xFF01 && cp <= 0xFF0F) || cp >= 0x1F000;
}

// Lower case of a non-ASCII code point (Latin-1, Latin Extended-A, Greek, Cyrillic: what the docs and translations use).
inline unsigned lower_unicode(unsigned cp) {
    if ((cp >= 0xC0 && cp <= 0xDE && cp != 0xD7) || (cp >= 0x391 && cp <= 0x3A9) || (cp >= 0x410 && cp <= 0x42F))
        return cp + 0x20;
    if (cp >= 0x400 && cp <= 0x40F) return cp + 0x50;
    if (cp >= 0x100 && cp <= 0x17F && cp != 0x130 && cp != 0x131 && cp != 0x178 && cp != 0x138 && cp != 0x149 &&
        cp != 0x17F) {
        const bool oddIsUpper = (cp >= 0x139 && cp <= 0x148) || (cp >= 0x179 && cp <= 0x17E);
        return (cp % 2 == (oddIsUpper ? 1u : 0u)) ? cp + 1 : cp;
    }
    return cp;
}

inline void append_utf8(std::string& out, unsigned cp) {
    if (cp < 0x80) {
        out += static_cast<char>(cp);
    } else if (cp < 0x800) {
        out += static_cast<char>(0xC0 | (cp >> 6));
        out += static_cast<char>(0x80 | (cp & 0x3F));
    } else if (cp < 0x10000) {
        out += static_cast<char>(0xE0 | (cp >> 12));
        out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (cp & 0x3F));
    } else {
        out += static_cast<char>(0xF0 | (cp >> 18));
        out += static_cast<char>(0x80 | ((cp >> 12) & 0x3F));
        out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (cp & 0x3F));
    }
}

// GitHub's anchor of a heading: lower case, markup dropped, everything but letters, digits, marks, '-', '_' and spaces
// removed (Unicode punctuation and symbols too), spaces become '-'. Letters of other scripts stay, lower-cased.
inline std::string slug_of(std::string heading) {
    // [text](url) -> text; `code` -> code; <tags> and emphasis marks vanish with the punctuation rule.
    std::string h;
    for (size_t i = 0; i < heading.size(); ++i) {
        if (heading[i] == ']' && i + 1 < heading.size() && heading[i + 1] == '(') {
            const size_t close = heading.find(')', i);
            if (close != std::string::npos) {
                i = close;
                continue;
            }
        }
        h += heading[i];
    }
    std::string out;
    for (size_t i = 0; i < h.size(); ++i) {
        const char ch = h[i];
        const unsigned char c = static_cast<unsigned char>(ch);
        if (c >= 0x80) {
            // One UTF-8 sequence (a malformed one is kept byte by byte).
            const size_t n = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : c >= 0xC0 ? 2 : 1;
            if (n == 1 || i + n > h.size()) {
                out += ch;
                continue;
            }
            unsigned cp = c & (0xFFu >> (n + 1));
            for (size_t k = 1; k < n; ++k) cp = (cp << 6) | (static_cast<unsigned char>(h[i + k]) & 0x3Fu);
            i += n - 1;
            if (!is_unicode_punctuation(cp)) append_utf8(out, lower_unicode(cp));
        } else if (std::isalnum(c))
            out += static_cast<char>(std::tolower(c));
        else if (c == '-' || c == '_')
            out += ch;
        else if (c == ' ')
            out += '-';
    }
    // Trailing/leading spaces of the heading text (not inner ones) are trimmed before: done by the caller.
    return out;
}

// The anchors a Markdown file offers: its headings (outside code fences), the repeated ones numbered -1, -2...
inline std::set<std::string> anchors_of(const std::string& text) {
    std::set<std::string> out;
    std::map<std::string, int> seen;
    for (const Line& l : split_lines(text)) {
        if (l.inFence) continue;
        size_t i = 0;
        while (i < l.text.size() && l.text[i] == '#') ++i;
        if (i == 0 || i > 6 || i >= l.text.size() || l.text[i] != ' ') continue;
        std::string h = l.text.substr(i + 1);
        while (!h.empty() && (h.back() == ' ' || h.back() == '#')) h.pop_back();
        while (!h.empty() && h.front() == ' ') h.erase(h.begin());
        const std::string slug = slug_of(h);
        const int n = seen[slug]++;
        out.insert(n == 0 ? slug : slug + "-" + std::to_string(n));
    }
    // Explicit anchors: <a id="x"> and <a name="x"> (outside code fences).
    for (const Line& l : split_lines(text)) {
        if (l.inFence) continue;
        for (size_t at = l.text.find("<a "); at != std::string::npos; at = l.text.find("<a ", at + 1)) {
            const size_t end = l.text.find('>', at);
            const std::string tag = l.text.substr(at, end == std::string::npos ? std::string::npos : end - at);
            for (const char* attr : {"id=\"", "name=\""}) {
                const size_t a = tag.find(attr);
                if (a == std::string::npos) continue;
                const size_t b = a + std::string(attr).size();
                const size_t q = tag.find('"', b);
                if (q != std::string::npos) out.insert(tag.substr(b, q - b));
            }
        }
    }
    return out;
}

struct Link {
    std::string target;  // as written, without a title
    int line = 0;        // 1-based
};

// The `](target)` links outside code fences and outside inline code spans.
inline std::vector<Link> links_of(const std::string& text) {
    std::vector<Link> out;
    const std::vector<Line> lines = split_lines(text);
    for (size_t n = 0; n < lines.size(); ++n) {
        if (lines[n].inFence) continue;
        const std::string& s = lines[n].text;
        bool inCode = false;
        for (size_t i = 0; i < s.size(); ++i) {
            if (s[i] == '`') {
                inCode = !inCode;
                continue;
            }
            if (inCode || s[i] != ']' || i + 1 >= s.size() || s[i + 1] != '(') continue;
            // The target ends at the first space or ')' (a title or the end of the link).
            size_t j = i + 2;
            int depth = 0;
            while (j < s.size() && s[j] != ' ' && !(s[j] == ')' && depth == 0)) {
                if (s[j] == '(') ++depth;
                if (s[j] == ')') --depth;
                ++j;
            }
            if (j >= s.size()) continue;  // no closing parenthesis: not a link
            out.push_back({s.substr(i + 2, j - (i + 2)), static_cast<int>(n) + 1});
        }
    }
    return out;
}

inline bool is_external(const std::string& t) {
    return starts_with(t, "http://") || starts_with(t, "https://") || starts_with(t, "mailto:") ||
           starts_with(t, "factoria://") || starts_with(t, "/") || starts_with(t, "<") ||
           t.find("://") != std::string::npos;
}

// The paragraph (lines up to the blank ones around) of a 1-based line, as one lower-case string.
inline std::string paragraph_around(const std::vector<Line>& lines, int line) {
    int a = line - 1;
    int b = line - 1;
    while (a > 0 && !lines[static_cast<size_t>(a) - 1].text.empty()) --a;
    while (b + 1 < static_cast<int>(lines.size()) && !lines[static_cast<size_t>(b) + 1].text.empty()) ++b;
    std::string p;
    for (int i = a; i <= b; ++i) p += lines[static_cast<size_t>(i)].text + "\n";
    std::transform(p.begin(), p.end(), p.begin(), [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    return p;
}

inline bool says_not_embedded(const std::string& paragraph) {
    return paragraph.find("not in the binary") != std::string::npos ||
           paragraph.find("repository only") != std::string::npos || paragraph.find("source docs") != std::string::npos;
}

}  // namespace fa_docs_test
